export interface RetryOptions { retries: number; baseMs: number }

export function delayFor(attempt: number, o: RetryOptions): number {
  return o.baseMs * 2 ** attempt;
}

export class RateLimiter {
  constructor(readonly perSecond: number) {}
}

// Request signing. Owned by Birch.
export interface Signer {
  sign(method: string, path: string, body: string): Promise<string>;
}

export interface ClientOptions { baseUrl: string }

export async function request(o: ClientOptions, path: string): Promise<Response> {
  return fetch(new URL(path, o.baseUrl));
}
